        // "sec-fetch-site": "same-origin",
        "user-agent": getFromCache("userAgent") || "",
        "x-csrf-token": getFromCache("pixivCsrfToken") || "",
        "Cookie": getFromCache("pixivCookie") || ""
    }
    putInCacheObject("headers", headers)
    return headers
}

