    commentIDs.forEach(commentID =>{
        sleep(0.5 * 1000 * Math.random())
        let resp = getPostBody(
            "https://www.pixiv.net/novel/rpc_delete_comment.php",
            `i_id=${novel.id}&del_id=${commentID}`
