function get1(url, header,_) {
	   const 	{cookie,java} = _||this;
    let html1 = java.get(url,header).body();
    return JSON.parse(html1);
}

function jiexi(path,size){
const 	{cookie,java} = this;
let cookie1 = cookie.getCookie("https://pan.baidu.com");
let pc_ua = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/81.0.4044.138 Safari/537.36";
let ua3 = "netdisk;P2SP;2.2.91.136;android-android;";
let header1 = {
    "User-Agent": pc_ua,
    "Cookie": cookie1
};
let header = Object.assign({}, header1, {"User-Agent": ua3});
        let html1 = get1("https://d.pcs.baidu.com/rest/2.0/pcs/file?app_id=250528&method=locatedownload&path="+encodeURIComponent(path)+"&use=1", header,this);       
        let url = html1.urls[0].url;
        if (size < 52428800) {
            return {url: url, header: header1};
        } else {
            return {url: url, header: header};
        }
    }

