        const url = `majax/category/list?${queryParams}&size=${size_dic[size]}&isfinish=${isfinish_dic[isfinish]}&gender=male&orderBy=${orderBy_dic[orderBy]}&pageNum={{page}}&_csrfToken={{cookie.getKey("https://qidian.com","_csrfToken")}}`;
        var sizeFactor;
        if (queryParams.includes('subCatId')) {
            sizeFactor = 0.25;
        } else {
            sizeFactor = 1;
        }
        push(title, url, sizeFactor);
    });
    JSON.stringify(result);

